{
  "name": "@whatcode-ai/whatcode",
  "version": "2.7.0",
  "description": "CLI to start opencode and optionally expose it over HTTPS via Tailscale — connect to your AI coding assistant from anywhere.",
  "keywords": [
    "opencode",
    "tailscale",
    "ai",
    "cli",
    "server",
    "https",
    "tunnel",
    "remote",
    "whatcode"
  ],
  "homepage": "https://www.whatcode.app/",
  "bugs": {
    "url": "https://github.com/Pnlvfx/whatcode-ai/issues"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/Pnlvfx/whatcode-ai.git",
    "directory": "packages/whatcode"
  },
  "license": "MIT",
  "author": {
    "name": "Simone Gauli",
    "email": "simonegauli@gmail.com"
  },
  "sideEffects": false,
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./logger": {
      "types": "./dist/logger.d.ts",
      "import": "./dist/logger.js"
    }
  },
  "bin": {
    "whatcode": "./dist/cli.js"
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@whatcode-ai/sdk": "2.7.0",
    "execa": "^10.2.1",
    "qrcode-terminal": "^0.12.0",
    "semver": "^7.8.5",
    "yargs": "^18.2.0",
    "zod": "^4.6.7"
  },
  "devDependencies": {
    "@eslint/config-helpers": "^0.7.0",
    "@goatjs/node-monorepo-eslint": "^3.47.0",
    "@goatjs/rimraf": "^2.15.0",
    "@goatjs/typescript-config": "^2.3.0",
    "@types/node": "^26.6.6",
    "@types/qrcode-terminal": "^0.12.2",
    "@types/semver": "^7.8.0",
    "@types/yargs": "^17.0.35",
    "eslint": "^10.14.0",
    "typescript": "^6.0.3"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "rimraf dist && tsc -p tsconfig.build.json && eslint",
    "lint": "eslint",
    "tsc": "tsc --noEmit"
  }
}
